import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷九","description":"周易经传集解 - 周易经传集解卷九","frontmatter":{"title":"周易经传集解卷九","description":"周易经传集解 - 周易经传集解卷九"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/010.md","filePath":"zh/classics/jingchuan-jijie/010.md"}'),r={name:"zh/classics/jingchuan-jijie/010.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷九",tabindex:"-1"},[n("周易经传集解卷九 "),e("a",{class:"header-anchor",href:"#周易经传集解卷九","aria-label":"Permalink to “周易经传集解卷九”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解随蛊卷九 ​宋林栗撰。序卦曰：「豫必有随，故受之以随。」「随」之成卦，「豫」之变也。自「豫」之「随」，震来居下，「坤」变为「兑」，相易而成也。震耒居下，动乎「坤」也。坤变为「兑」，说乎「震」也。刚来下柔，则柔随之，动而说，所以为随也。夫豫之为言，安逸而怠惰者也。安逸而怠惰，不能复振，则死期至矣。豫而不死，其必有所随乎？昧爽而兴，何悔怠，是之谓「随」也矣。是故自「豫」之「随」，上变六五，下变初六，而随之象可见矣。变初为九，则「鸣豫」之㓙，为「有渝」之「吉」。变五为九，则乘刚之疾，为「嘉吉」之孚。以「豫」之上体，为随之下体，上居震之终，下居震之始，故上六「成有渝，无咎」，而初九「官有渝，贞吉」，盖相因之辞也。学者顾以刚来下柔为豫之变，不已疏乎？随：元亨利贞，无咎。彖曰：「随」，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时。随时之义大矣哉！下震上兑，成卦曰「随」者，初为震，二为艮，三为巽，四为兑。震为春，巽为夏，兑为秋，艮为冬，四时之义备矣。震为元，巽为亨，兑为利，艮为贞，四德之行成矣。夫人者，随天者也。臣者，随君者也。天有四时，人之所随也。君有四德，臣之所随也。故曰：「随，元亨利贞，无咎。」四时不傋，则寒暑失序，人不可以随天。四德不具，则威福旡章，下不可以随上。「元亨利贞」四者无咎，而后天下随之矣。孟子曰：「身不行道，不行于妻子。」其是之谓乎？子曰：随，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时。随时之义大矣哉！「刚来」下柔，「震」下「兑」上也。「动而说」，亦「震」「兑」也。九五者，「随」之主也。初九者，随之言也。惟其下之，是以上之也。「随之」二字重复，故传写讹误。朱氏曰：「王肃本作随之，今定读云。大亨贞无咎，而天下随之。随之时义大矣哉！」彖称四德，而夫子但言「大亨贞」，何也？「元」尽乎「大」，而利兼乎「亨」也。「随」之时义，于斯为大矣。其详已见屯彖。鲁穆姜之筮也，曰：「有四德者，随而无咎，我皆无之，岂随也哉？」呜呼！穆姜其知道矣，而不能制淫慝之心，以陷于大恶，惜乎其悔之晚也。象曰：泽中有雷，「随」。君子以向晦入宴息。「泽」者，「兑」也。「雷」者，「震」也。泽中有雷，泽之所「随」也。雷上于天，则泽气随之而升。雷下于泽，则泽气随之而降。耿氏曰：「雷之发声以仲春，仲春，震也。其收声以仲秋，仲秋，兑也。」雷出地奋，乃发声于震之时，故为豫。泽中有雷，乃收声于兑之时，故为随。震以动出为材，故震为雷。然之收声于兑，以随时而已。是故君子体之，以向晦入宴息。日出而明，君子随之而作；日入而晦，君子随之而息。随之时义也。震为日出，兑为日入故也。传曰：「君子有四时：朝以听政，昼以访问，夕以修令，夜以安身。」此之谓也。系曰：「服牛乘马，引重致远，以利天下，盖取诸随。」何也？曰：泽者随雷者也，雷者随时者也；人者随天者也，牛马随人者也，臣随君者也，妻随夫者也，学者随师者也。自虽圣人，未有能干时而动者，随之时义，顾不大哉？杂卦曰：「随，无故也。」随之为卦，以兑随震而成。其在六爻，以所随为义。书曰：「德无常师，主善为师；善无常主，恊于克一。」是以随之时义，不主于故常，惟其可以随则随之也。夫阳者，阴之所随也；上者，下之所随也。然初九之随六二，则以下爻随上爻，而非阴之随阳也。上六之随九五，则以阴爻随阳爻，而非下之随上也。是之谓「无故也」。夫随也者，当位而相应则随之也，六二之随九五是已。然六三之随九四，则以近而相与，非当位而相应也。夫「随」也者，一阴而一阳则随之也。两刚不能以相事，两柔不能以相使，则无相随之义也，六二之于六三是已。然九四之于九五，则两爻皆刚而有相随之义，何也？是之谓无故也。夫无故者，必有其故也。王之所在，阳不可以不随于阴；弟之所反，上不可以不随于下。有之于上，虽近而不害于随；有位于中，虽均而不敢随也。随之无故，不其然乎？是故九五居中履正，孚于二四。初九，随二者也；六三，随四者也，固已旡思不服矣。至于上六处卦之终，居五之上，虽欲勿随，不可得也。此象所谓「大亨贞无咎」，而天下随之者也。初九：官有渝，贞吉。出门交有功。象曰：「官有渝」，从正吉也；「出门交有功」，不失也。初九，「震」也。以阳居刚而在下卦之下，上无其应，而「随」六二之「艮」，故曰：「官有渝，贞吉，出门交有功。」「官」者，主宰之谓也。所以为「随」者，「震」也。所以为「震」者，初九也。故有「官」之象焉。「官」也者，人之所随，而非随人者也。然尧舜禹汤不能旡过，苟固执而不变，宁咈百姓以从己，不肯舍己以从人，亡之道也。孔子有言：「如其善而莫之违也，不亦善乎？如不善而莫之违也，不几乎一言而丧邦乎？」「渝」者，变也。变而从正，则「吉」也。故曰：「贞吉」。从善如流，改过不吝，以此为「贞」，宜其「吉」矣。然为物之主，而惟人是随。所随不正，则陷于邪僻矣；所随不广，则陷于私昵矣。故曰：「出门交有功。」初九为「震」，「震」为出；六二为「艮」，「艮」为门阙，故有「出门」之象焉。以六居二，则所随者正矣。出门遇二，遂与之交，则所随者广矣。所随者正，则不悖于道；所随者广，则不失于人。吉且「有功」，不亦宜乎？故子曰：官有渝，从正吉也。「出门交有功，不失也。」六二在「豫」说为中正矣，初六阴柔，不能从正，以成「鸣豫」之凶，至于是而从之，斯能变凶为吉也。或曰：子以震为出，艮为门阙，则「同人」初、二以离遇巽，亦有出门之象，何哉？曰：由「艮」而出乎「震」，由「巽」而相见乎「离」，「艮」、「震」皆阳，「离」、「巽」皆阴，其为出门之遇一也。然「同人」之门，取诸全象之则；而「随」之门，取诸「艮」、「震」之交，盖不一而足矣。六二：系小子，失丈夫。象曰：「系小子」，弗兼与也。六二，「艮」也。以阴居柔，而在下卦之中，应乎九五之「兑」，上随六三，而下为初九之所随者也。故曰：「系小子，失丈夫」。初为「震」，「震」为长男，故有「丈夫」之象。三有「艮」体，二之于三，三之于四，四之于五，皆「艮」，「艮」为少男，故有「小子」之象。「系」，牵也。初之于二，势之所牵也。然初之于二，四之于五，其所随者正，而非以其势随之也，是以不谓之系也。若六三、九四不得其正，而有随之者，岂非其所系之故欤？夫君子之所为随者，谓理义之所在，而人心之所同然者也。苟为其所系而随之，有所系则有所失矣。系邪而失正，君子不为也；系小而失大，君子不为也。六二在「豫」，所谓「上交不謟，下交不渎」者。及其在随，所系者六三而已。三以阴柔不当其位，岂君子之所宜随哉？系于三，则失于初矣。初九，正也；六三不正也。初震丈夫也；三艮小子也。夫初之所以随二者，以二之中正，故舍己而从之也。一系于三，则丧其正矣，其失于初九，宜哉！夫以六二上应九五，下交初九，无不得其正矣。其于六三，虽有所系，必不肯枉道以从之也。然二爻皆柔，同体乎「艮」，故为之戒云尔。子曰：「系小子，弗兼与也。」使其系于小子而不失于丈夫，狥于一人之欲而不咈天下之情，则何恶于诡随也哉！惟其邪正小大弗可以兼与，是以君子见几而作也。六三：系大夫，失小子。随有求得，利居贞。象曰：「系丈夫」，志舍下也。六三下体为「艮」，上体为「巽」，以阴居刚而在下卦之上，上无其应而随于九四，故曰：「系丈夫，失小子」。二为「艮」，「艮」为「小子」。四有震体，「震」为「丈夫」。三系于四，则失于二矣。三之系四而失二，与二之系三而失初，一也。然而三可以系于四，二不可以系于三，何也？曰：三，「艮」也，而四则「兑」也。三，「巽」也，而四则「震」也。三，六也，而四则九也。居上下之交，在人伦之位，相与以成，相须以立者也。系而随之，不亦可乎？方随之时，九五在天，上下之所共随也。三远于五，不系于四，无以达焉。二自配五，反系于三，失之远矣。丈夫者，人之所随也；「小子」者，随人者也。是以系失同而否臧异也。或曰：二中正而谓之「小子」，何也？曰：君子小人，何常之有？立其大则为大人，狥其小则为小人。使二不能自立而惟三之随，其谓之小子也宜哉！故曰「随有求得」。以「艮」而求「兑」，则得之矣；以「巽」而求「震」，则得之矣；以六而求九，则得之矣；以三而求四，则得之矣；此其所以随之也。然志在随人，有求则得，将无所不至矣，故曰「利居贞」。三止而「巽」，其能居贞矣哉！故子曰「系丈夫，志舍下也」。「舍」，上声读。「下」谓二也。九四：随有获，贞㓙有孚，在道以明，何咎？象曰：「随有获」，其义凶也。「有孚在道」，明功也。九四上体为「兑」，下体为「震」，以阳居柔，而在上卦之下，下无其应，而上随九五，下为六三之所随也，故曰「随有获」，随人而有获也。「随」之九四，即「豫」之九四也。在「豫」为「有得」，在「随」为「有获」。随者，五也；「获」者三也。随五而获，三五之所不能，旡疑也。随人而不免于疑，失其道矣。获人之财，犹谓之盗，况获君之民乎？故曰「贞㓙」。以此为「贞」，「凶」其宜也。战国之际，齐有孟尝，赵有平原，楚有春申，魏有信陵。此四公子尊贤而下士，天下之有材智者，不远千里而归之。当是之时，列国相倾，以士为重。然其时君犹不能堪。至于汉兴，相国萧何为民请苑，以高皇之大度，犹不免械击之辱。其后魏其、武安，招致宾客，人主切齿，卒以诛灭。故卫将军以为招贤选士，人主之柄，人臣何得招士？惩此祻也。古之人如伊尹、周公，以身任天下之重，受天下之归，而无所顾忌于其间，其必有道矣。故曰：「有孚在道，以明何咎？」惟其忧国之诚心，泽民之素志，有以取信于上。上之人知其志在于行道，而非有背公营私、附下罔上之趣也，非有招权固位、欺君盗国之谋也。苟有以自明，何咎之有？昔者伊尹在畎亩之中，幡然而起曰：「吾岂若使是君为尧舜之君，使是民为尧舜之民？天之生是人也，使先知觉后知，先觉觉后觉。予将以斯道觉斯民也。」周公勤劳王家，卑躬下士，一饭三吐哺，一沐三握发，惟恐失天下之贤人，亲执贽而见者千人，还贽而相见者三千人，貌执之士百有余人，欲言而请毕事者千有余人。二公之行不同，其有获于斯民一也。而汤武在上，未尝置纤芥之疑，岂非「有孚在道，其志自明」也哉？故子曰：随有获，其义凶也。有孚在道，明功也。五不孚四，旡以获三，四之于五，可谓有功矣。有孚于上则为功，无以自明则为贼。处斯地者，可不鉴兹哉？曰：豫之有得，随之有获，其义一也。一则为大，一则为㓙，何也？曰：非其有而得之谓之获。豫之所承者，六五也。五非四无以得民，是以为大也。随之所承者，九五也。五居正中，而四获于下，是以为㓙也。九五：孚于嘉，吉。象曰：「孚于嘉，吉」，位正中也。九五，「兑」也，以阳居刚，而在上卦之中，应乎六二之「艮」，而为上下之所随者也。故曰：「孚于嘉吉。」「嘉」，犹配也。昏礼谓之「嘉」，传曰「嘉偶」，曰「妃子」，曰嘉会，足以合礼是也。不曰「配」而曰「嘉」者，「嘉」之言美也，贤人君子之谓也。九五之所谓「嘉」者，其六二之谓乎？二为「艮」，五为「兑」，有感应相与之象焉，夫是以谓之「嘉」也。二五交孚，人莫能间，君臣之义，夫妇之道，于是为至矣。天下以平，家国以治，谓之「吉」也，不亦宜乎？或曰：二于五为嘉，而下交于初九，何也？曰：初九者，五之未得其位，而来下于柔者也。卦以「随」为义，初随二者也，非二之随初也。其于初也，为出门之交；其于五也，为「嘉偶」之「孚」矣。五位乎天，刚柔上下，莫不随之，然后六二之「嘉」始合也。故子曰：「孚于嘉吉，位正中也。」或曰：五虽中正，何以见刚柔上下莫不随之？曰：二，五之配也；四，五之邻也。其随之也，不占而决以六三、初九，远非其配，近非其邻，三系于四，初交于二，是以随之也。二四则有功于五矣。故初曰「有功」，四曰「明功」，互发其文也。若上六穷而无归，舍五何适哉？或曰：子以初九为九五下柔之象，又曰初交于二，所以随五也。义孰从乎？曰：「自豫」之「随」，其变者初与五也。九五来中，而初九在下，是以为刚来下柔也。及其正中矣，则初九者岂非因二以随五者乎？是谓「大亨贞无咎」，而天下随之也。上六：拘系之，乃从维之。王用享于西山。象曰：「拘系之」，上穷也。上六，「巽」也。以阴居柔，而在上卦之上，下无其应，而随于九五之「兑」，故曰：「拘系之，乃从维之。」「巽」为绳，故有系维之象。柔之为物，不能独立，必有所系。在卦二阴，惟三上有「巽」体，故三系于四，上系于五。至于六二，虽承六三，而不体乎「巽」，是以系而不系也。夫随也者，自下随上也。今上六以阴柔之资，而居九五之上，本非随五，而又非五之所随也。然而居一卦之上，上无所随，下无所应，而五位中正，天下随之，上六虽欲勿随，不可得矣。五之于上也，其来不拒，其去不追，非有必于其随也。上六穷而无归，其势必将挽九五而随之，是以谓之「拘系」也。上拘而系之，五乃从而维之。人之随我，我不得已而受之，又从而维之以恩，结之以信，则其随我也，绸缪固结而不可解，此周之王业所由兴也。故王用享于西山。「兑」为西方，故有西山之象。西山，岐周也。太王避狄而去邠，邠人曰：「仁人也，不可失也。」从之者如归市，不得已而邑于岐山之下居焉，是谓「拘系之乃从维之」也。逮于文王，小心事纣，而海滨二老归就其养，虞、芮二国来质厥成，其享不亦宜乎？诗云：「天作高山，太王荒之。彼作矣，文王康之。彼徂矣，岐有夷之行，子孙保之。」此之谓也。子曰：「拘系之，上穷也。」穷上者必反下，是以上六之于九五，有「拘系」之象也。其当殷之末世，周之盛德耶？序卦曰：「以喜随人者必有事，故受之以蛊。蛊者，事也。」「蛊」之成卦，随之反也。自「随」之「蛊」，六爻尽变而成也。所以为「随」者，刚来下柔也；及其为「蛊」，则刚上柔下矣。所以为「随」者，动而说也；及其为「蛊」，则「巽」而止矣。杂卦曰：「随，无故也。」序卦曰：「以喜随人者必有事。」传不云乎，「无故者，必有其故也。」圣人深究天下万物之情状，知其无故而「以喜随人」，必将有事焉，是故受之以「蛊」也。老子曰：「将欲取之，必姑与之。」其「随蛊」之序乎？子曰：蛊者，事也。扬雄作大玄，其准蛊也，以务与事。尚书大传曰：乃命五史，以书五帝之蛊事。然则「蛊」之训「事」，其来尚矣。春秋左氏：「赵孟问秦医曰：何谓蛊？对曰：淫溺惑乱之所生也。于文，皿虫为蛊，谷之飞亦为蛊。在易，女惑男，风落山，谓之蛊。」是以学者疑焉。为之说曰：「器久不用而虫生之，谓之蛊；人久宴溺而疾生之，谓之蛊，天下久安无为而弊生之，谓之蛊。」夫蛊非事也，以天下为无事而不事事，则后将有不胜事矣。此蛊之所以为事也，是固然矣。然文王、孔子彖、象、序、杂，皆「元亨利涉」之辞，而不复言宴安湛溺之义。今将取正于秦医之论「女惑男，风落山谓之蛊」，则于彖、象之情矛盾而不合。愚为更之曰：「蛊」之训「事」，犹「乱」之训「治」也。书盘庚曰：「乱越厥家。」梓材曰：「厥乱为民。」义皆训「治」。不言「治」而言「乱」者，乱而治之，非守成之治也。今易之「蛊」，义皆训「事」，不言「事」而言「蛊」者，蛊而有事，非循常之事也。是故「乱」既训「治」，不复言「乱」；「蛊」既训「事」，不复言「蛊」。系曰：「穷则变，变则通，通变之谓事。」此之谓也。故彖言「利涉」，象曰「育德振民」，序言「有事」，杂卦言「饬」。商之三宗，周之宣王，应其义矣。蛊：元亨，利涉大川，先甲三日，后甲三日。彖曰：「蛊，刚上而柔下，巽而止，蛊。蛊元亨」，而天下治也。「利涉大川」，往有事也。「先甲三日，后甲三日」，终则有始，天行也。下巽上艮成卦曰「蛊」者，初为巽，二为兑，三为震，四为艮。巽为风，震为雷，艮为山，兑为泽。风雷者，所以鼓舞万物者也；而山泽者，所从受之者也，是以谓之蛊也。蛊以艮、巽成卦。巽，长女也；艮，少男也。男虽少而在上，女虽长而在下。六五、九二，艮、兑相交，而刚柔上下不失其正，是以谓之蛊也。巽，巽也；艮，止也。止而不巽，则无以顺天下之情；巽而不止，则无以立天下之极。巽而止，所以为蛊也。故子曰：「刚上而柔下，巽而止，蛊。」「蛊，元亨，利涉大川。」何谓也？曰：蛊之四象，止以巽于随，其为「元亨利贞」，宜与随同，而象不言贞者，随下震而上兑，震仲春而兑仲秋也，震旦而兑夕也。蛊下巽而上艮，巽在春夏之交，而艮在冬春之际，巽非日中而艮非夜半，故曰失贞之象，本职诸艮，蛊之上艮，宜系之贞矣，然而独不言之，何也？蛊，事也；贞者，事之干也，干立而后枝叶有所遂。今以蛊为卦，而元亨与利兼之，虽不言「贞」，可以互见之矣。虽不言「贞」，而系之「先甲」「后甲」，则终始之义备矣。君子之立事也，智以谋之，信以守之，发而为仁，达而为礼，行而为义。有所不为，为之而无不成；有所不革，革之而无不就。故曰「蛊元亨而天下治也」。「利涉大川」，何谓也？曰：巽为木，兑为泽，震为足，艮为山，木浮于泽而足履于山，利涉之象也。方蛊之时，非垂拱无为而治者也，必有所涉而后济焉。书曰：「若涉渊水，予惟往求朕攸济」是也。若畏其难而惮其劳，则宴安苟且，终于委靡而已矣。故子曰：「利涉大川，往有事也」。「先甲三日，后甲三日」，何谓也？曰：甲者，震也。「蛊」之上九为震先甲也；九三为震，后甲也。盖自大挠造甲子，起于五行，自甲至癸，为天一地十之数，自子至亥，为乾坤十二位之象。甲卯，东方木也，在易为「震」；庚酉，西方金也，在易为「兑」。圣人作易起于八卦，其见于爻象者，不言其卦而言其物。「蛊」之三，上有震体，不谓之震而谓之甲。「巽」之三，上有兑体，不谓之兑而谓之庚。先甲三日起于子而终于寅，后甲三日起于卯而终于巳。寅者，艮也。巳者，「巽」也。至是而一阴生矣。先庚三日起午而终于申，后庚三日起酉而终于亥。申者，坤也。亥者，乾也。阴极而阳生矣。圣人于此著消息之义焉。蛊之六爻，上为震，四为艮，先甲三日，起子而尽于寅也。三为震，初为巽，后甲三日，起卯而终于巳也。甲、卯、震同位而异名，初之于四，三之于上，其相去也，皆以三爻，是以系之三日也。故曰「先甲三日，后甲三日，终则有始，天行也」。圣人贵阳而贱阴，好治而恶乱。后甲在巽，一阴之候，圣人之所惧也。故因艮巽之中有重震之象，而著其义焉。天下之物，未有成而不坏者，天下之事，未有新而不敝者。阳于此终，阴于此始，天运之行，𫝑将至之。物极则反，道穷则变，变而通之，乃可以久，是则蛊「元亨利涉」之义也。若夫先庚后庚，其象为离。离者午也。阴起午而终亥，然后一阳生焉，故曰「无初有终」。所以然者，自蛊而巽变，六五一爻而成之，一爻之变，而先后有甲庚之异，言易者可以不求其故而狥其臆说也哉？或曰：「子以蛊之艮巽明后甲先甲之象，既有征矣。先庚为坤，后庚为乾，而巽之六位，上下反复，不见乾坤之象，何也？」曰：同归而殊涂，一致而百虑。蛊之先甲「后甲，既取诸震，又取诸艮巽，而义既明矣。巽」之「先庚」「后庚」，既取诸「兑」，又取诸九五，五为「离」，先庚之所起也，其义不又明乎哉？「巽」之无乾坤，犹「蛊」之无「坎」也，而可以一义必之邪？使其爻象往复，无以相异，则既言于「蛊」，不必出之于「巽」矣。「蛊」以「艮巽」成卦，故著于象。「巽」以「离」象居五，故系于爻。学者详思焉，庶乎其得之矣。苏氏曰：先甲三日，子、戌、申也。申尽于巳，而阳盈矣。盈将上阴，治将生乱，故授之以后甲。后甲三日，午、辰、寅也。寅尽于亥，然后阴极而阳生。「蛊」九五以干之，故其治乱皆极其自然之势。势穷而后变，故曰：「终则有始，天行也。若夫先庚三日，午、辰、寅也。后庚三日，子、戌、申也。庚之所后，甲之所先也。先庚尽于亥，后庚尽于己，先阴而后阳，先乱而后治，故曰：无初有终」。又曰：「不言于象而言于五者，明此九五之功，非巽之功也」。其说虽晦，而理亦深然若如深谕，当言「先甲三旬」，不当言「三日」也。且于「蛊」之四象无所发明，故存而不取。象曰：山下有风，「蛊」。君子以振民育德。「山」者，「艮」也。「风」者，「巽」也。风行山下，有振动生育之象。不动则不生，不振则不育，故君子体之，以振民而育德焉。振民则取诸风，育德则取诸山也。孔子曰：「君子之德风，小人之德草。草上之风，必偃。」孟子曰：「匡之直之，辅之翼之，使自得之，又从而振德之。」此之谓也。而秦医之论，以为女惑男，风落山，谓之蛊。夫摇落之风，曷为行于山下？媚惑之女，曷为长于少男？吾不知其说也。学者信传而疑经，岂不过甚矣哉？杂卦曰：「蛊则饬也。」饬，治也，谨也。刚上而柔下，蛊之所以为饬也。刚上而柔下，君臣、父子、夫妇皆然矣。蛊之为事，非循常之事也，有自下饬上之义焉。施之君臣之间，夫妇之际，义或未安，故直以父子明之。「蛊」之诸爻，上下反复，皆震、巽、艮、兑之象。震，长男也；巽，长女之任也。少男二女，非其任矣，故但以先甲。巽，长女也。艮，少男也。兑，少女也。父在而干其蛊者，后甲明其义焉。甲者，震也。先后者，以上下言之也。上震三爻，父也；下震三爻，子也。子虽干蛊，不先于父，此蛊之所以为饬也。诸家旧说，皆随爻取义，不以相应求之。盖见六四言「裕父之蛊」，六五言「干父之蛊」，二爻在上故也。此所谓以文害辞，以辞害意也。其在他卦，初九相应之义者，见其爻辞，疑若相应，又从而牵合之，以此求易，宜其不通也。愚岂好辨哉？诚不得已也。如诸家之论，九二「干母之蛊」，六四「裕父之蛊」，犹稍异于诸爻，乃若「干父之蛊」，二爻同称，何以别其优劣乎？初六曰：「干父之蛊，有子，考旡咎，厉终吉。」而象曰：「意承考也。」六五曰：「干父之蛊，用誉。」而象曰：「承以德也。」二爻不同，其义安在？九三又曰：「干父之蛊，小有悔，无大咎。」而象曰：「终无咎也。」夫易之为书，所以教人君国齐家，而示之以吉凶悔吝者也。为人子而干父之蛊，当用柔乎？抑用刚乎？苟刚柔杂用而无所适从，是圣人之惑之也。此乃经之过也。其失在于不按卦以求义，而执文以害辞也。譬如入人之室，一父而五子，则父为家主，子皆从父者也；一母而五子，则母为家主，子皆从母者也。若兄弟同居，则其妻妾若子各从其主者也。是故卦有五阳而一阴、五阴而一阳者；有二阳而四阴、二阴而四阳者，阴阳各居其半者，各以其类别之也。其或应或不应者，则又随其卦义而辨之也。随之诸爻，以男女长少为义，或以远而相应，或以近而相随，或以上而随下，或以阳而随阴。而「蛊」之诸爻，以父子为义，上三爻为父，下三爻为子。视其应与不应，而吉㓙悔吝可见矣。故曰：「随无故也，蛊则饬也。」不既明甚矣乎？初六：干父之蛊，有子，考无咎，厉终吉。象曰：「干父之蛊」，意承考也。初六，「巽」也，以阴居刚而在下卦之下，其应六四，四以阴居柔而体乎「艮巽」，故曰：「干父之蛊」。「巽」，长女也；「艮」，少男也。「艮」「巽」同居，莫能有制，「蛊」之所以为「蛊」也。四之象道可谓不振矣。初虽居刚，有干蛊之才，而四以阴柔，志不相应，「巽」以承父，不失其为子之道矣。有子之贤，虽偾必起，故曰：「有子，考无咎。」生谓之「父」，殁谓之「考」。「有子」者，有其才而未用也。当父之时，初虽干蛊而势未得行，见志不从，又敬不违，四之不振，犹自若也，安能免于咎乎？父殁而子克家，则为「无咎」矣。故曰：「厉终吉」。父「巽」乎上，子「巽」乎下，家道不振，亦已危矣。有子克家，故「终吉」也。子曰：「干父之蛊，意承考也。」论语曰：「父在，观其志，父没观其行。」其此之谓欤！九二：干母之蛊，不可贞。象曰：「干母之蛊」，得中道也。九二，「兑」也，以阳居柔而在下卦之中，应乎六五之阴，故曰：「干母之蛊」。「艮」为少男，「兑」为少女，有感应相与之义焉。二以阳居柔，而五以阴居刚，不约而孚矣。夫母从子者也，子从母者也。母柔而子刚，于义为得矣。然而不可以为贞也，有母在上，而专以刚行之，有时而违咈矣。唯九三居柔体说，履得其中，孝以事亲，义以干蛊，刚柔适中，子道尽矣。故子曰：「干母之蛊，得中道也。」九三：干父之蛊，小有悔，无大咎。象曰：「干父之蛊」，终无咎也。九三上体为「震」，下体为「兑」，以阳居刚而在下之上，其上九，上亦「震」也，上震下「巽」，所谓「先甲后甲」者也。二爻俱阳，若不相应，乃传家而主器者也。故曰：「干父之蛊。」上九，贤父也；九三，贤子也，皆阳刚而体「震」故也。三爻体「兑」，说以从父也。上九知其子之贤，而释其器之重，自处于优游无事之域，而以干蛊之任委之。三受任于父，得以事行无所顾忌，则其不应焉者，乃所以为任之专也。家事大小，不必咨而后行也。故曰：「小有悔，无大咎。」父在而子专行，虽父之命，然内外之事、上下之情，其能无小悔乎？上九之贤，既已知其子而任之矣。三之所为，皆干父之蛊，而非狥其私者也，是以虽「小悔」而「无大咎」也。故子曰：「干父之蛊，终无咎也。」或曰：子以「巽」「艮」同居，为四之不振，三亦「震」「兑」同居也，乌在其为贤子乎？曰：女长而男少，则男听于女；男长而女少，则女听于男。三以阳居刚，而四以阴居柔，不可以同年而语之矣。六四：裕父之蛊，往见吝。象曰：「裕父之蛊」，往未得也。六四上体为艮，下体为「巽」，以阴居柔而在上卦之下，下应初六，二爻俱阴，无相得之义，故曰：「裕父之蛊」。「裕」，益也。传曰：「以水济水，以火济火，名之曰益」，多裕蛊之谓也。「巽」为长女，「艮」为少男。长女少男，莫适为正，不可以为干蛊之子，益父之事而已。故曰：「往见吝」。初六干蛊之子欲往而饬之，父为之主，不应于己，宜其「见吝」也。或曰：初、四皆巽也，一为男，一为女；一为贤，一为不肖，何也？曰：下三爻为子，皆有「巽」「兑」之象，为女，无干蛊之义，则「巽」「兑」者，上之所以事亲。上三爻为父，而「艮」「巽」居焉，则是长女少男相与陷父于不义者也。初以「巽」居刚，而四「巽」以居柔，牝牡贤愚，于此可见矣。故子曰：「裕父之蛊，往未得也。」其在初六曰：「意承考也。」所以互明之欤？六五：干父之蛊，用誉。象曰：「干父用誉」，承以德也。六五，「艮」也，以阴居刚而在上卦之中，应乎九三之「兑」，故曰：「干父之蛊」。「艮」，止也；「兑」，说也。六五，贤母也；九二，贤子也。妇人旡家，以夫为家。母虽在上，而所干者父之事也。不曰「夫」而曰「父」者，从子而言也。六五为母，则九三干母之事者也，故曰：「用誉」。母以柔干乎上，子以刚干乎下，上下相应，内外相与，德盛而教尊，家肥而誉显，不亦宜乎？故子曰：「干父用誉，承以德也。」或曰：六五为母，而「艮」居之，不亦裕蛊之象乎？曰：少男者，母之所保抱携持者也。以六居五，应乎九二，无「裕蛊」之嫌矣。上九：不事王侯，高尚其事。象曰：「不事王侯」，志可则也。上九，「震」也。以阳居柔，而在上卦之上，其应九三，「震」、「兑」也。二「震」重刚，无相与之义，故曰「不事王侯」。王者，五也；「侯」者，二也。在五之上而不应五，「不事王侯」之象也。夫「蛊」者，事也；「震」者，动也。当「蛊」之事而体乎「震」，宜若有为者矣。然而「蛊」之终也，终则变矣。九三之「震」既已能任其事，上九超然远举，不累于物，脱于是非利害之涂，而出乎尘垢粃糠之外，是乃「不事王侯」者也。「不事王侯」何义也？大夫七十而致政，老而传家者也，故曰「高尚其事」。上九之「不事」，非不能事事也，年高而德卲，其所事者皆高尚于世俗而不屑为其细也。是以外致其位，内得其家，优游无为，委任贤子，享「期颐」之寿，得「令终」之名也。人之所贵乎有子孙者，为其死而有所托，老而有所传耳。昧者乃以「不事王侯」为君子之高节，然则周公之勤劳，仲尼之历聘，皆失节而不正者也。圣人吉凶与民同志，而乃以「不事」为高，岂不小哉？治则见，乱则隐，方元亨利涉之时，非俭德避难之日，「不事王侯」，其义安在？故曰：「大夫七十而致政，老而传家者也。」壮而能事，老而能传，知足不辱，知止不殆，故子曰：「不事王侯，志可则也。」易有君臣、父子、夫妇之道焉，尊卑奠位，则三者同其义也。阴阳相求，必著夫妇之义；远近咸应，多取君臣之教。若夫蛊者，父子之义也，施之于君臣则悖矣。故初六有志而不敢往，九二「刚中」而不可贞，子道也，非臣道也。九三子得专行，「有悔」而无咎，子道也，亦非臣道也。人君虽高拱旡为，委任臣下，终不能如上九之不事事也。故爻皆以父子明之，而六五有「干父用誉」之辞，上九有「不事王侯」之义。以国言之，则五为王而二为侯；以家言之，则五为妻而三为子。易之取义，不一而足，皆如是矣。礼曰：「事君有犯而无隐，事亲有隐而无犯。」同归或殊涂也。禅位之帝，继体之君，可则以观于蛊矣。周易经传集解卷九。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
